const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

module.exports = peers_inspector

async function peers_inspector(opts = {}, protocol, { onClose } = {}) {
  const { sdb } = await get(opts.sid)
  const { drive } = sdb
  const on = { style: inject, data: ondata, icons: onicons }
  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <section class="inspector-page">
      <header class="topbar"><button class="back-button" data-action="back" aria-label="Back">‹</button><div><p>Lightning network</p><h1>Peers</h1></div><span class="readonly-badge">Read only</span></header>
      <div class="loading-state"><span class="loading-ring"></span><p>Reading peer connections…</p></div>
      <div class="error-state hidden"><span>!</span><strong>Peer diagnostics unavailable</strong><p></p></div>
      <div class="loaded-state hidden">
        <div class="peer-summary"></div>
        <div class="peer-list"></div>
        <div class="empty-state hidden"><span>↔</span><strong>No peers reported</strong><p>This node currently has no Lightning peer records.</p></div>
        <p class="captured-at"></p>
      </div>
      <section class="peer-detail hidden"></section>
    </section>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const sendUp = protocol ? protocol(receiveFromParent) : null
  let snapshot = null
  let loadTimer = null

  await sdb.watch(onbatch)
  shadow.addEventListener('click', handleClick)
  el.open = function () { closePeer(); load() }
  return el

  function handleClick(event) {
    const action = event.target.closest('[data-action]')
    if (action?.dataset.action === 'back' && onClose) onClose()
    if (action?.dataset.action === 'close-peer') closePeer()
    const peerRow = event.target.closest('[data-peer-index]')
    if (peerRow && snapshot) openPeer(Number(peerRow.dataset.peerIndex))
    const tab = event.target.closest('[data-peer-tab]')
    if (tab) {
      const detail = shadow.querySelector('.peer-detail')
      detail.querySelectorAll('[data-peer-tab]').forEach(button => button.classList.toggle('active', button === tab))
      detail.querySelector('.details-panel').classList.toggle('hidden', tab.dataset.peerTab !== 'details')
      detail.querySelector('.raw-panel').classList.toggle('hidden', tab.dataset.peerTab !== 'raw')
    }
  }

  function load() {
    if (loadTimer) window.clearTimeout(loadTimer)
    snapshot = null
    closePeer()
    showState('loading')
    request({ type: 'get_diagnostics_peers', data: {} })
    loadTimer = window.setTimeout(function () {
      if (snapshot) return
      shadow.querySelector('.error-state p').textContent = 'The diagnostics request timed out. Check that the Flamingo backend and Lightning node are running.'
      showState('error')
    }, 8000)
  }

  function receiveFromParent(message) {
    if (message?.type !== 'diagnostics_peers_loaded') return
    const response = message.data || {}
    if (response.status !== 'success' || !response.data) {
      shadow.querySelector('.error-state p').textContent = friendlyError(response.error)
      showState('error')
      return
    }
    if (loadTimer) window.clearTimeout(loadTimer)
    snapshot = response.data
    showState('loaded')
    renderList()
  }

  function renderList() {
    const peers = snapshot?.peers || []
    const connected = peers.filter(peer => peer.connected !== false).length
    const disconnected = peers.length - connected
    shadow.querySelector('.peer-summary').innerHTML = `${summaryMetric('Connected', connected, 'green')}${summaryMetric('Disconnected', disconnected, disconnected ? 'red' : '')}${summaryMetric('Total', peers.length, '')}`
    const list = shadow.querySelector('.peer-list')
    list.innerHTML = peers.map(function (peer, index) {
      const online = peer.connected !== false
      const channels = peer.channels || []
      const log = peer.log || []
      const latestError = [...log].reverse().find(entry => String(entry.type || '').toLowerCase().includes('unusual') || String(entry.type || '').toLowerCase().includes('broken'))
      return `<button class="peer-row" data-peer-index="${index}"><span class="peer-dot ${online ? 'online' : 'offline'}"></span><span class="peer-copy"><strong>${escapeHtml(peer._alias || 'Unknown peer')}</strong><small class="mono">${escapeHtml(shortId(peer.id || 'ID unavailable'))}</small><em>${channels.length} channel${channels.length === 1 ? '' : 's'}${latestError ? ' · issue reported' : ''}</em></span><span class="peer-state ${online ? 'connected' : 'disconnected'}">${online ? 'Connected' : 'Offline'}</span><span class="chevron">›</span></button>`
    }).join('')
    shadow.querySelector('.empty-state').classList.toggle('hidden', peers.length !== 0)
    const time = new Date(snapshot.captured_at)
    shadow.querySelector('.captured-at').textContent = `Snapshot captured ${Number.isNaN(time.getTime()) ? snapshot.captured_at : time.toLocaleString()}`
  }

  function openPeer(index) {
    const peer = snapshot?.peers?.[index]
    if (!peer) return
    const online = peer.connected !== false
    const channels = peer.channels || []
    const netaddr = Array.isArray(peer.netaddr) ? peer.netaddr.join(', ') : (peer.netaddr || 'Not reported')
    const detail = shadow.querySelector('.peer-detail')
    detail.innerHTML = `
      <header class="detail-header"><button data-action="close-peer" aria-label="Back to peers">‹</button><div><small>Peer details</small><strong>${escapeHtml(peer._alias || 'Unknown peer')}</strong></div><span class="peer-state ${online ? 'connected' : 'disconnected'}">${online ? 'Connected' : 'Offline'}</span></header>
      <div class="content-tabs"><button class="active" data-peer-tab="details">Details</button><button data-peer-tab="raw">Raw JSON</button></div>
      <div class="details-panel">
        <article class="identity-card"><small>Node ID</small><strong>${escapeHtml(peer.id || 'Unavailable')}</strong></article>
        <article class="detail-card">${row('Network address', netaddr)}${row('Connection', online ? 'Connected' : 'Disconnected')}${row('Direction', peer.incoming === true ? 'Incoming' : peer.incoming === false ? 'Outgoing' : 'Not reported')}${row('Channels', channels.length)}${row('Features', peer.features || 'Not reported')}</article>
        <article class="log-card"><h2>Peer log</h2>${renderLog(peer.log || [])}</article>
      </div>
      <div class="raw-panel hidden"><pre>${escapeHtml(JSON.stringify(peer, null, 2))}</pre></div>
    `
    shadow.querySelector('.loaded-state').classList.add('hidden')
    detail.classList.remove('hidden')
    shadow.querySelector('.inspector-page').scrollTop = 0
  }

  function closePeer() {
    shadow.querySelector('.peer-detail').classList.add('hidden')
    if (snapshot) shadow.querySelector('.loaded-state').classList.remove('hidden')
  }

  function renderLog(log) {
    if (!log.length) return '<p class="no-log">No peer log entries were returned.</p>'
    return `<div class="log-list">${log.slice(-20).reverse().map(entry => `<div class="log-entry"><span>${escapeHtml(entry.type || 'info')}</span><p>${escapeHtml(entry.log || entry.message || JSON.stringify(entry))}</p></div>`).join('')}</div>`
  }
  function showState(state) {
    shadow.querySelector('.loading-state').classList.toggle('hidden', state !== 'loading')
    shadow.querySelector('.error-state').classList.toggle('hidden', state !== 'error')
    shadow.querySelector('.loaded-state').classList.toggle('hidden', state !== 'loaded')
  }
  function request(message) { if (typeof sendUp === 'function') sendUp({ from: 'peers_inspector', ...message }) }
  function summaryMetric(label, value, tone) { return `<div class="summary-metric ${tone}"><strong>${value}</strong><small>${label}</small></div>` }
  function row(label, value) { return `<div class="detail-row"><span>${label}</span><strong title="${escapeHtml(String(value))}">${escapeHtml(String(value))}</strong></div>` }
  function shortId(value) { return value.length > 24 ? `${value.slice(0, 12)}…${value.slice(-8)}` : value }
  function friendlyError(error) { const text = String(error || 'The backend did not return peer information.'); return text.includes('ECONNREFUSED') ? 'The Lightning node is not reachable. Check that the Flamingo backend is running.' : text }
  function escapeHtml(value) { return String(value).replace(/[&<>"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[char]) }
  async function onbatch(batch) { for (const { type, paths } of batch) { const data = await Promise.all(paths.map(path => drive.get(path).then(file => file.raw))); await (on[type] || fail)(data, type) } }
  function inject(data) { style.textContent = data[0] }
  function ondata() {}
  function onicons() {}
  function fail(data, type) { throw new Error('invalid message', { cause: { data, type } }) }
}

function fallback_module() {
  return { api: fallback_instance }
  function fallback_instance(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}
    return { drive: { 'icons/': {}, 'style/': { 'style.css': { '$ref': 'peers_inspector.css' } }, 'data/': { 'opts.json': { raw: opts || {} } } } }
  }
}
